	[3478] = { position = { 7557585, 0.27, 0.645 }, spells = { 1283034, 1283081 }, note = { "The Deathless Marrow fight brings in guardians, watchers and sorcerers. Control their shield slams, charges and fireballs.", "Im Kampf gegen das unsterbliche Mark greifen Wächter, Beobachter und Zauberer ein. Achtet auf Schildschläge, Anstürme und Feuerbälle." }, approximate = true },
	[3511] = { note = { "This encounter is hidden in an underwater room connected to the central pool.", "Die Begegnung liegt in einem Unterwasserraum, der mit dem zentralen Becken verbunden ist." } },
	[3479] = { position = { 7557585, 0.168, 0.662 }, spells = { 1283295, 1283313, 1313471, 1283327, 1283233, 1283250, 1283266 }, note = { "Move early when the boss changes form and keep clear of the area attacks.", "Bewegt euch frühzeitig, wenn der Boss seine Gestalt ändert, und weicht den Flächenangriffen aus." }, approximate = true },
	[3480] = { position = { 7473414, 0.355, 0.426 }, spells = { 3604, 1316382 }, note = { "Clear the nearby packs. Ranged players can stay beyond the reach of Dust Storm.", "Räumt die Gegnergruppen in der Nähe. Fernkämpfer können sich außerhalb des Staubsturms halten." }, approximate = true },
	[3481] = { position = { 7473414, 0.283, 0.451 }, spells = { 12054, 14100, 18501 }, note = { "Control the two hunters and clear a space to fight before pulling. The roar can send players running into nearby packs.", "Kontrolliert die beiden Jäger und schafft vor dem Kampf Platz. Das Brüllen kann Spieler in weitere Gegner treiben." }, approximate = true },
	[3644] = { position = { 7473414, 0.225, 0.475 }, approximate = true },
	[3482] = { position = { 7473414, 0.303, 0.499 }, spells = { 15588 }, note = { "Use the archival panel to start the fight. Ranged players can stay outside Thunderclap.", "Startet den Kampf am Archivpult. Fernkämpfer können Abstand zum Donnerknall halten." }, approximate = true },
	[3353] = { position = { 7255712, 0.622, 0.635 }, spells = { 3358 }, note = { "The spider patrols King's Alley with two escorts. Kill them first and cleanse the tank's poison.", "Die Spinne patrouilliert mit zwei Begleitern. Tötet zuerst die Begleiter und entfernt das Gift vom Tank." }, approximate = true },
	[3357] = { position = { 7255712, 0.435, 0.664 }, spells = { 1266011, 14907 }, note = { "Activate the statue on Market Street and defeat the waves that follow. The boss roots nearby players and drains health from the tank.", "Aktiviert die Statue in der Marktstraße und besiegt die folgenden Gegnerwellen. Der Boss friert Spieler in seiner Nähe fest und entzieht dem Tank Leben." }, approximate = true },
	[3355] = { position = { 7255712, 0.554, 0.738 }, spells = { 17307 }, note = { "The Baron can knock back the tank and reduce their threat. Leave room between the group and nearby packs.", "Der Baron kann den Tank zurückstoßen und seine Bedrohung senken. Haltet Abstand zu den umliegenden Gegnern." }, approximate = true },
	[3411] = { position = { 7255712, 0.428, 0.713 }, spells = { 3358 }, note = { "Lighting the fireplace near the graveyard starts the waves that lead to Viktor.", "Entzündet den Kamin nahe dem Friedhof, um die Gegnerwellen vor Viktor auszulösen." }, approximate = true },
	[3412] = { position = { 7255712, 0.437, 0.567 }, spells = { 1301635 }, note = { "Bjork briefly shields himself against magic.", "Bjork schützt sich kurz mit einem Schild gegen Magie." }, approximate = true },
	[3354] = { position = { 7255712, 0.469, 0.688 }, spells = { 18399 }, note = { "Leave the area under the tank as soon as Flamestrike starts.", "Verlasst die Fläche unter dem Tank, sobald der Flammenstoß beginnt." }, approximate = true },
	[3450] = { position = { 7540085, 0.294, 0.699 }, spells = { 1280085, 11428, 21049 }, note = { "Watch for knockdowns and the damage increase from Bloodlust.", "Achtet auf das Niederschlagen und den erhöhten Schaden während Kampfrausch." }, approximate = true },
	[3452] = { position = { 7540085, 0.391, 0.641 }, spells = { 1280011, 8599, 12057 }, note = { "Move away when Zarmok starts his whirl.", "Geht auf Abstand, sobald Zarmok seinen Wirbel beginnt." }, approximate = true },
	[3453] = { position = { 7540085, 0.6, 0.5 }, spells = { 1282076, 9128 }, note = { "Ashka fights with a beast and can order it to attack.", "Ashka kämpft mit einem Tier und kann es zum Angriff befehligen." }, approximate = true },
	[3449] = { position = { 7540085, 0.375, 0.556 }, spells = { 1280259, 1280356 }, note = { "Watch for Convert and Shadow Bolt Volley.", "Achtet auf die Bekehrung und die Schattenblitzsalve." }, approximate = true },
	[3451] = { position = { 7540085, 0.632, 0.272 }, spells = { 1282394, 1282387, 1282393, 1282397 }, note = { "Mugg swaps weapons during the fight. Watch for Crushing Slam.", "Mugg wechselt im Kampf seine Waffen. Achtet auf seinen Schmetterschlag." }, approximate = true },
	[3493] = { position = { 7726092, 0.484, 0.762 }, spells = { 26048, 1292602 }, note = { "Clear part of the patrol room and interrupt Mind Blast. Remove the curse from the tank if possible.", "Räumt einen Teil des Raums frei und unterbrecht Gedankenschlag. Entfernt den Fluch vom Tank, wenn möglich." }, approximate = true },
	[3495] = { position = { 7726092, 0.843, 0.6 }, spells = { 1293228, 11970 }, note = { "The elemental is accompanied by a summoner. Kill the summoner first and keep ranged players clear of Fire Nova.", "Ein Beschwörer begleitet den Elementar. Tötet ihn zuerst. Fernkämpfer halten Abstand zur Feuernova." }, approximate = true },
	[3494] = { position = { 7726092, 0.484, 0.638 }, spells = { 10101 }, note = { "Pull the patrolling golem away from nearby packs. Fight with a wall behind you to limit its knockback.", "Zieht den patrouillierenden Golem aus der Nähe anderer Gegner. Eine Wand im Rücken fängt den Rückstoß ab." }, approximate = true },
	[3496] = { position = { 7726092, 0.484, 0.371 }, spells = { 26070, 12054 }, note = { "Clear the room before pulling. The group can flee into nearby enemies. Focus the two golems one at a time.", "Räumt den Raum vor dem Kampf. Furcht kann euch in weitere Gegner treiben. Tötet die beiden Golems nacheinander." }, approximate = true },
}
